#include "../core/execution_engine.hpp"
#include "../core/tool.hpp"
#include "../llm/fake_backend.hpp"
#include "../util/logger.hpp"
#include <iostream>
#include <cassert>
#include <vector>
#include <string>
#include <filesystem>
#include <fstream>

using namespace platypus::core;
using namespace platypus::llm;

namespace fs = std::filesystem;

void setup_test_workspace(const std::string& root) {
    if (fs::exists(root)) {
        fs::remove_all(root);
    }
    fs::create_directories(root);
}

void run_e2e_test(const std::string& name, const std::string& task, const std::string& workspace, const std::string& expected_file, const std::string& expected_content) {
    std::cout << "Running test: " << name << "..." << std::endl;

    setup_test_workspace(workspace);

    auto backend = std::make_shared<FakeBackend>();

    // Script the tool call for a "write_file" action.
    // We expect the LLM to respond with a JSON tool call.
    // The codec handles JSON tool calls.

    // Turn 1: Agent sees the task and decides to use `write_file`.
    backend->set_script("write_file_task", {
        "{\"tool_call\": {\"name\": \"write_file\", \"arguments\": {\"path\": \"./test_workspace_1/test_file.txt\", \"content\": \"Hello E2E\"}}}"
    });

    auto tool_registry = std::make_shared<ToolRegistry>();
    register_filesystem_tools(*tool_registry);
    register_search_tools(*tool_registry);
    register_shell_tools(*tool_registry);

    ExecutionEngine engine(backend, tool_registry);

    auto result = engine.run(task);

    assert(result.is_ok());
    std::cout << "Task completed successfully." << std::endl;

    // Verify results
    fs::path test_file(expected_file);
    assert(fs::exists(test_file));

    std::ifstream ifs(test_file);
    std::string content((std::istreambuf_iterator<char>(ifs)), std::istreambuf_iterator<char>());
    assert(content.find(expected_content) != std::string::npos);

    std::cout << "Test " << name << " PASSED!" << std::endl;
}

int main() {
    // Test 1: Simple File Creation
    run_e2e_test(
        "Simple File Creation",
        "write_file_task",
        "./test_workspace_1",
        "./test_workspace_1/test_file.txt",
        "Hello E2E"
    );

    return 0;
}

#ifndef PLATYPUS_CORE_CONTEXT_MANAGER_HPP
#define PLATYPUS_CORE_CONTEXT_MANAGER_HPP

#include <vector>
#include <string>
#include <memory>
#include "../llm/backend.hpp"
#include "../util/result.hpp"

namespace platypus::core {

/**
 * @brief Manages the conversation history, sliding window, and summarization.
 * 
 * This class ensures that the conversation history remains within reasonable limits
 * by using a sliding window and summarizing older turns when the limit is exceeded.
 */
class ContextManager {
public:
    /**
     * @brief Constructs the ContextManager.
     * @param backend The LLM backend to use for summarization.
     * @param max_history The maximum number of history turns to keep in the sliding window.
     */
    ContextManager(std::shared_ptr<llm::LlmBackend> backend, size_t max_history = 20);

    /**
     * @brief Adds a new turn to the conversation history.
     * @param role The role of the turn (e.g., "user", "assistant", "system").
     * @param content The content of the turn.
     */
    void add_turn(const std::string& role, const std::string& content);

    /**
     * @brief Checks if history exceeds max_history_ and generates a summary if necessary.
     */
    void update();

    /**
     * @brief Returns the current conversation history.
     */
    std::vector<std::pair<std::string, std::string>> get_history() const;

    /**
     * @brief Returns the current context summary.
     */
    std::string get_summary() const;

private:
    /**
     * @brief Generates a summary of the intermediate conversation turns.
     * @return A result indicating success and the summary string.
     */
    util::Result<std::string> generate_summary();

    std::shared_ptr<llm::LlmBackend> backend_;
    std::vector<std::pair<std::string, std::string>> history_;
    size_t max_history_;
    std::string context_summary_;
};

} // namespace platypus::core

#endif // PLATYPUS_CORE_CONTEXT_MANAGER_HPP

